import { build } from "esbuild";
import { execSync } from "node:child_process";
import path from "node:path";
import zlib from "node:zlib";

const mode = process.argv[2];
const ROOT = process.cwd();
const srcDir = path.join(ROOT, "src") + path.sep;

const entries = {
  "H3Core": `import { H3Core } from "./src/index.ts"; const app = new H3Core();`,
  "defineHandler": `import { defineHandler } from "./src/index.ts"; const handler = defineHandler({});`,
};

for (const [name, code] of Object.entries(entries)) {
  const res = await build({
    bundle: true,
    write: false,
    minify: true,
    format: "esm",
    platform: "node",
    outfile: "index.mjs",
    treeShaking: true,
    conditions: ["browser"],
    logOverride: { "ignored-bare-import": "silent" },
    stdin: { contents: code, resolveDir: ROOT, sourcefile: "index.mjs", loader: "js" },
    plugins: [
      {
        name: "head-src",
        setup(b) {
          b.onLoad({ filter: /\.ts$/ }, (args) => {
            if (mode !== "head" || !args.path.startsWith(srcDir)) return undefined;
            const rel = path.relative(ROOT, args.path).split(path.sep).join("/");
            const contents = execSync(`git show HEAD:${rel}`, { encoding: "utf8" });
            return { contents, loader: "ts" };
          });
        },
      },
    ],
  });
  const text = res.outputFiles[0].text;
  console.log(`${mode} ${name}: bytes=${Buffer.byteLength(text)} gzip=${zlib.gzipSync(text).byteLength}`);
}

